function downloadCsv(filename:string, headers:string[], rows:(string|number)[][]){
 const escape=(value:unknown)=>`"${String(value??'').replace(/"/g,'""')}"`;
 const csv=[headers.map(escape).join(','),...rows.map(row=>row.map(escape).join(','))].join('\r\n');
 const url=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8;'}));
 const anchor=document.createElement('a');anchor.href=url;anchor.download=filename;document.body.appendChild(anchor);anchor.click();anchor.remove();URL.revokeObjectURL(url);
}
function downloadPdf(filename:string,title:string,lines:string[]){
 // Generate a compact, valid text-based PDF directly in the browser; no print dialog or server needed.
 const ascii=(value:string)=>value.normalize('NFKD').replace(/[^\x20-\x7E]/g,'');
 const esc=(value:string)=>ascii(value).replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)');
 const content=['BT','/F1 18 Tf','50 790 Td',`(${esc(title)}) Tj`,'/F1 10 Tf','0 -28 Td',...lines.flatMap((line)=>[`(${esc(line).slice(0,150)}) Tj`,'0 -18 Td']),'ET'].join('\n');
 const objects=[
  '<< /Type /Catalog /Pages 2 0 R >>',
  '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
  '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>',
  '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',
  `<< /Length ${new TextEncoder().encode(content).length} >>\nstream\n${content}\nendstream`
 ];
 let pdf='%PDF-1.4\n';const offsets=[0];
 objects.forEach((obj,i)=>{offsets.push(new TextEncoder().encode(pdf).length);pdf+=`${i+1} 0 obj\n${obj}\nendobj\n`});
 const xref=new TextEncoder().encode(pdf).length;pdf+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`;
 for(let i=1;i<offsets.length;i++)pdf+=`${String(offsets[i]).padStart(10,'0')} 00000 n \n`;
 pdf+=`trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
 const url=URL.createObjectURL(new Blob([pdf],{type:'application/pdf'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=filename;document.body.appendChild(anchor);anchor.click();anchor.remove();URL.revokeObjectURL(url);
}
