function StartPage(){const [industry,setIndustry]=useState<Industry|' '>(' ');const [plan,setPlan]=useState('14-day Free Trial');const navigate=useNavigate();return <main className="welcome-layout"><aside className="welcome-brand-panel"><Brand light/><div className="welcome-brand-copy"><h1>One platform.<br/><em>Any business.</em></h1><p>Manage customers, operations, team members and business files in one place.</p>{[['Users','Customers & Contacts','Keep every relationship organized'],['Activity','Industry-specific Operations','Healthcare, retail, real estate and more'],['FileText','Invoices, Payments & Files','Create and manage business documents'],['ShieldCheck','Team & Permissions','Manage your team and access'],['Activity','Reports & Insights','Understand your business at a glance']].map((x,i)=><div className="welcome-feature" key={x[1]}><span>{i===0?<Users size={17}/>:i===1?<Activity size={17}/>:i===2?<FileText size={17}/>:i===3?<ShieldCheck size={17}/>:<Activity size={17}/>}</span><div><b>{x[1]}</b><small>{x[2]}</small></div></div>)}</div><div className="welcome-illustration"><div className="welcome-device"><div className="device-top"><i/><i/><i/></div><div className="device-metrics"><span/><span/><span/></div><div className="device-chart"><svg viewBox="0 0 240 80" preserveAspectRatio="none"><path d="M0 68 L28 55 L58 61 L87 35 L118 44 L149 20 L181 31 L210 8 L240 14" fill="none" stroke="#3b82f6" strokeWidth="3"/><path d="M0 68 L28 55 L58 61 L87 35 L118 44 L149 20 L181 31 L210 8 L240 14 L240 80 L0 80Z" fill="#3b82f6" opacity=".12"/></svg></div><div className="device-lines"><i/><i/><i/></div></div><div className="welcome-glow"/></div><small className="welcome-copyright">© 2026 Happy Technologies</small></aside><section className="welcome-content"><header className="welcome-topbar"><span>GET STARTED</span><span>Already have an account? <Link to="/login">Sign in</Link></span></header><div className="welcome-content-inner"><div className="welcome-progress"><span className="current"><b>1</b> Industry</span><i/><span><b>2</b> Plan</span><i/><span><b>3</b> Register</span></div><h2>Choose your industry and plan</h2><p className="welcome-subtitle">Choose the industry that best fits how your business works.</p><div className="welcome-section-label"><b>1. Select your industry</b><small>{industry===' '?'Choose one':'Selected'}</small></div><div className="welcome-industry-grid">{industries.map(({name,desc,icon:Icon})=><button type="button" key={name} className={'welcome-industry '+(industry===name?'selected':'')} onClick={()=>setIndustry(name)}><span className="welcome-industry-icon"><Icon size={19}/></span><span><b>{name}</b><small>{desc}</small></span><span className="welcome-radio">{industry===name&&<i/>}</span></button>)}</div><div className="welcome-section-label plan-label"><b>2. Choose free trial or paid plan</b><small>Start free, or continue with a paid package</small></div><div className="welcome-plan-grid">{plans.map(p=><button type="button" key={p.name} onClick={()=>setPlan(p.name)} className={'welcome-plan '+(plan===p.name?'selected':'')}><span className="welcome-plan-name">{p.name}{plan===p.name&&<CheckCircle2 size={14}/>}</span><strong>{p.price}</strong><span>{p.users}</span></button>)}</div><div className="welcome-bottom-actions"><span><ShieldCheck size={14}/> Free trial needs no payment · Paid plans continue to demo checkout</span><button className="btn btn-primary" disabled={industry===' '} onClick={()=>{sessionStorage.setItem('hbs_industry',industry);sessionStorage.setItem('hbs_plan',plan);navigate('/register')}}>Continue <ArrowRight size={16}/></button></div><p className="welcome-trial-note">The 14-day trial skips checkout. Paid-plan checkout is a demo only; no real payment is processed.</p></div></section></main>}
function AuthShell({children,title,subtitle,mode}:{children:React.ReactNode;title:string;subtitle:string;mode:string}){return <div className="auth-page"><aside className="auth-brand-panel"><Brand light/><div className="auth-panel-copy"><span className="eyebrow">HAPPY BUSINESS SUITE</span><h1>One platform.<br/><em>Any business.</em></h1><p>Manage customers, operations, invoices, team members and business files in one place.</p>{['Customers & Contacts','Industry-specific Operations','Invoices, Payments & Files','Team & Permissions','Reports & Insights'].map((t,i)=><div className="benefit" key={t}><span><Check size={15}/></span><b>{t}</b></div>)}</div><div className="auth-illustration"><div className="mini-window"><div className="mini-top"><i/><i/><i/></div><div className="mini-stat-row"><b/><b/><b/></div><div className="mini-chart"><i/><i/><i/><i/><i/><i/><i/></div><div className="mini-lines"><i/><i/><i/></div></div><div className="orb orb-one"/><div className="orb orb-two"/></div><div className="auth-panel-foot">© 2026 Happy Technologies</div></aside><main className="auth-main"><div className="auth-mobile-brand"><Brand/></div><div className="auth-card"><div className="auth-step-label">{mode.toUpperCase()}</div><h2>{title}</h2><p className="auth-subtitle">{subtitle}</p>{children}</div></main></div>}
function LoginPage(){const [show,setShow]=useState(false);const [remember,setRemember]=useState(true);const [error,setError]=useState('');const [busy,setBusy]=useState(false);const navigate=useNavigate();return <AuthShell mode="Sign in" title="Welcome back" subtitle="Sign in to your business workspace and continue where you left off."><form onSubmit={async e=>{e.preventDefault();setError('');setBusy(true);const f=new FormData(e.currentTarget);try{const result=await api<any>('/auth/login',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password')})});sessionStorage.setItem('hbs_token',result.token);sessionStorage.setItem('hbs_account',JSON.stringify({name:result.user.fullName,email:result.user.email,phone:result.user.phone||''}));if(result.workspace){sessionStorage.setItem('hbs_workspace',JSON.stringify(result.workspace));const label=({'clinic':'Clinic / Healthcare','hotel':'Hotels / Hospitality','courier':'Courier / Logistics','real_estate':'Real Estate'} as Record<string,string>)[result.workspace.industry]||'Clinic / Healthcare';sessionStorage.setItem('hbs_industry',label);sessionStorage.setItem('hbs_plan',result.workspace.planCode==='business'?'Growth':result.workspace.planCode==='professional'?'Core':'14-day Free Trial');}navigate('/app');}catch(err){setError(err instanceof Error?err.message:'Sign in failed.');}finally{setBusy(false)}}}><label>Work email<div className="input-icon"><Mail size={16}/><input name="email" required type="email" placeholder="you@company.com"/></div></label><label>Password<div className="input-icon"><Lock size={16}/><input name="password" required type={show?'text':'password'} placeholder="Enter your password"/><button type="button" className="icon-button" onClick={()=>setShow(!show)}>{show?<EyeOff size={16}/>:<Eye size={16}/>}</button></div></label><div className="form-between"><label className="checkbox-label"><input type="checkbox" checked={remember} onChange={e=>setRemember(e.target.checked)}/> Remember me</label><button type="button" className="text-button" onClick={()=>alert('Please contact support to reset your password in this first backend-connected version.')}>Forgot password?</button></div>{error&&<p className="form-error" role="alert">{error}</p>}<button className="btn btn-primary full" disabled={busy} type="submit">{busy?'Signing in…':'Sign in'} <ArrowRight size={16}/></button><p className="auth-switch">Don't have an account? <Link to="/">Create account</Link></p></form></AuthShell>}
function RegisterPage(){const [show,setShow]=useState(false);const industry=sessionStorage.getItem('hbs_industry')||'';const plan=sessionStorage.getItem('hbs_plan')||'14-day Free Trial';const isTrial=plan==='14-day Free Trial';return <AuthShell mode="Create your account" title="Create your account" subtitle="Your workspace starts here. Business details can be added later in Settings."><div className="registration-summary"><span>{industry||'Industry not selected'}</span><b>{plan}</b><Link to="/">Change</Link></div><form onSubmit={async e=>{e.preventDefault();const form=e.currentTarget;const data=new FormData(form);const submit=form.querySelector('button[type=submit]') as HTMLButtonElement|null;if(submit)submit.disabled=true;try{const result=await api<any>('/auth/register',{method:'POST',body:JSON.stringify({fullName:data.get('fullName'),email:data.get('email'),phone:data.get('phone'),password:data.get('password'),industry:industryCode(industry),planCode:planCode(plan)})});sessionStorage.setItem('hbs_token',result.token);sessionStorage.setItem('hbs_account',JSON.stringify({name:result.user.fullName,email:result.user.email,phone:result.user.phone||''}));sessionStorage.setItem('hbs_workspace',JSON.stringify(result.workspace));window.location.href=isTrial?'/app/import':'/payment';}catch(err){alert(err instanceof Error?err.message:'Registration failed.');if(submit)submit.disabled=false;}}}><label>Full name<input name="fullName" required autoComplete="name" placeholder="Your full name"/></label><label>Work email<input name="email" required type="email" autoComplete="email" placeholder="you@company.com"/></label><label>Phone number<input name="phone" required type="tel" autoComplete="tel" placeholder="+91 98765 43210"/></label><label>Password<div className="input-icon"><Lock size={16}/><input name="password" required minLength={8} type={show?'text':'password'} autoComplete="new-password" placeholder="At least 8 characters"/><button type="button" className="icon-button" aria-label={show?'Hide password':'Show password'} onClick={()=>setShow(!show)}>{show?<EyeOff size={16}/>:<Eye size={16}/>}</button></div></label><button className="btn btn-primary full" type="submit">Create account <ArrowRight size={16}/></button><p className="auth-switch">Already have an account? <Link to="/login">Sign in</Link></p></form></AuthShell>}
function PaymentPage(){
 const navigate=useNavigate();
 const plan=sessionStorage.getItem('hbs_plan')||'Core';
 const industry=sessionStorage.getItem('hbs_industry')||'';
 const account=JSON.parse(sessionStorage.getItem('hbs_account')||'{"name":"","email":""}');
 const price=plan==='Growth'?'₹2,00,000+':'₹1,50,000+';
 const [status,setStatus]=useState<'ready'|'complete'>('ready');
 const completeDemoPayment=()=>{
  sessionStorage.setItem('hbs_payment_status','demo-complete');
  setStatus('complete');
  window.setTimeout(()=>navigate('/import'),700);
 };
 return <AuthShell mode="Demo checkout" title={status==='complete'?'Demo payment complete':'Review your plan'} subtitle="This is a frontend-only checkout preview. No real payment will be taken.">
  <div className="payment-summary"><div><span>Selected industry</span><b>{industry||'Not selected'}</b></div><div><span>Plan</span><b>{plan}</b></div><div><span>Account</span><b>{account.email||'Your account'}</b></div><div className="payment-total"><span>Displayed plan price</span><strong>{price}</strong></div></div>
  <div className="demo-payment-notice"><ShieldCheck size={18}/><span><b>Demo payment only</b><small>Do not enter card details. This button simulates a successful checkout for testing the user flow.</small></span></div>
  <button className="btn btn-primary full" onClick={completeDemoPayment} disabled={status==='complete'}>{status==='complete'?'Payment simulated':'Simulate successful payment'} <CreditCard size={16}/></button>
  <button className="btn btn-ghost full payment-back" onClick={()=>navigate('/register')}>Back to registration</button>
 </AuthShell>
}

function SetupPage(){const [step,setStep]=useState(0);const [name,setName]=useState('Happy Clinic');const [industry,setIndustry]=useState<Industry>('Clinic / Healthcare');const [type,setType]=useState('Clinic');const [done,setDone]=useState(false);if(done)return <div className="setup-success"><div className="success-mark"><CheckCircle2 size={48}/></div><h1>You're all set!</h1><p>Your workspace is ready to use. Let's get your business running.</p><div className="summary-box"><b>Business name</b><span>{name}</span><b>Industry</b><span>{industry}</span><b>Plan</b><span>Solo</span></div><Link to="/app" className="btn btn-primary full">Go to Dashboard <ArrowRight size={16}/></Link></div>;return <div className="setup-page"><header className="setup-header"><Brand/><button className="text-button" onClick={()=>window.location.href='/'}>Save and exit</button></header><main className="setup-content"><div className="setup-intro"><div className="eyebrow">CREATE WORKSPACE</div><h1>Set up your <em>business.</em></h1><p>Tell us about your business. You can personalize your workspace later.</p></div><Stepper step={step===0?0:step===1?1:2}/><section className="setup-form"><div className="setup-form-title"><span className="field-icon">{step===0?<Building2/>:step===1?<MapPin/>:<SlidersHorizontal/>}</span><div><h2>{['Business profile','Business address','Preferences'][step]}</h2><p>{['Basic details about your business.','Where your business is located.','Choose how your workspace should behave.'][step]}</p></div></div>{step===0&&<div className="form-grid"><label>Business name<input value={name} onChange={e=>setName(e.target.value)} required/></label><label>Industry<select value={industry} onChange={e=>setIndustry(e.target.value as Industry)}>{industries.map(i=><option key={i.name}>{i.name}</option>)}</select></label><div className="full-field"><span className="field-label">Business type</span><div className="radio-grid">{['Clinic','Hospital','Diagnostic Center','Other'].map(t=><label key={t} className="radio-label"><input type="radio" name="businessType" checked={type===t} onChange={()=>setType(t)}/>{t}</label>)}</div></div><label>Phone number<input placeholder="+91 98765 43210"/></label><label>Website (optional)<input placeholder="https://"/></label></div>}{step===1&&<div className="form-grid"><label className="full-field">Address line 1<input placeholder="Street address"/></label><label>Address line 2 (optional)<input placeholder="Apartment, suite, etc."/></label><label>City<input placeholder="Bengaluru"/></label><label>State<input placeholder="Karnataka"/></label><label>PIN code<input placeholder="560001"/></label><label>Country<select defaultValue="India"><option>India</option><option>United States</option><option>United Kingdom</option></select></label></div>}{step===2&&<div className="form-grid"><label>Timezone<select defaultValue="Asia/Kolkata"><option value="Asia/Kolkata">(GMT+05:30) India Standard Time</option><option>UTC</option></select></label><label>Date format<select><option>DD/MM/YYYY</option><option>MM/DD/YYYY</option><option>YYYY-MM-DD</option></select></label><label>Currency<select><option>INR — Indian Rupee (₹)</option><option>USD — US Dollar ($)</option><option>GBP — Pound Sterling (£)</option></select></label><div className="privacy-callout"><ShieldCheck size={17}/> Your business information is stored securely and only accessible to authorized workspace members.</div></div>}<div className="setup-actions">{step>0?<button className="btn btn-ghost" onClick={()=>setStep(step-1)}><ArrowLeft size={16}/> Back</button>:<span className="muted-note">Step {step+1} of 3</span>}<button className="btn btn-primary" onClick={()=>step<2?setStep(step+1):setDone(true)}>{step<2?'Next':'Complete setup'} <ArrowRight size={16}/></button></div></section><p className="setup-footnote">You can update these details at any time in Settings.</p></main></div>}
