function CustomersPage(){const [q,setQ]=useState('');const [filter,setFilter]=useState('All Customers');const [showAdd,setShowAdd]=useState(false);const [rows,setRows]=useState<string[][]>([]);const [apiError,setApiError]=useState('');useEffect(()=>{api<any>('/customers').then(r=>setRows((r.items||[]).map((c:any)=>[c.fullName,c.phone||'',c.email||'', 'Active',new Date(c.createdAt).toLocaleDateString('en-IN')]))).catch(e=>setApiError(e.message));},[]);const [newName,setNewName]=useState('');const [newPhone,setNewPhone]=useState('');const [newEmail,setNewEmail]=useState('');const filtered=rows.filter(r=>(r[0]+r[2]).toLowerCase().includes(q.toLowerCase())&&(filter==='All Customers'||r[3]===filter));return <><PageHeading title="Customers" subtitle="Manage your customers and keep track of important details." action={<button className="btn btn-primary" onClick={()=>setShowAdd(true)}><Plus size={16}/> Add Customer</button>}/>{apiError&&<p className="form-error" role="alert">{apiError}</p>}<div className="mini-tabs"><button className={filter==='All Customers'?'active':''} onClick={()=>setFilter('All Customers')}>All Customers <span>{rows.length}</span></button><button className={filter==='Active'?'active':''} onClick={()=>setFilter('Active')}>Active</button><button className={filter==='Inactive'?'active':''} onClick={()=>setFilter('Inactive')}>Inactive</button></div><section className="panel table-panel"><div className="table-toolbar"><div className="table-search"><Search size={16}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search customers..."/></div><button className="btn btn-outline" onClick={()=>setFilter('All Customers')}><Filter size={15}/> Filters</button><button className="btn btn-outline" onClick={()=>downloadCsv('customers.csv',['Name','Phone','Email','Status','Added date'],filtered)}><Download size={15}/> Export</button></div><div className="table-wrap"><table><thead><tr><th><input type="checkbox" aria-label="Select all"/></th><th>Name</th><th>Phone</th><th>Email</th><th>Status</th><th>Added date</th><th/></tr></thead><tbody>{filtered.map((r,i)=><tr key={r[0]}><td><input type="checkbox" aria-label={'Select '+r[0]}/></td><td><span className="table-person"><span className="person-avatar blue">{r[0].split(' ').map(x=>x[0]).join('')}</span><b>{r[0]}</b></span></td><td>{r[1]}</td><td>{r[2]}</td><td><span className={'status '+(r[3]==='Active'?'status-green':'status-gray')}>{r[3]}</span></td><td>{r[4]}</td><td><button className="icon-button" aria-label="More actions"><MoreHorizontal size={18}/></button></td></tr>)}</tbody></table></div><div className="table-footer"><span>Showing {filtered.length} of {rows.length} customers</span><div className="pagination"><button disabled><ChevronLeft size={16}/></button><button className="page-active">1</button><button>2</button><button>3</button><button><ChevronRight size={16}/></button></div></div></section>{showAdd&&<div className="modal-backdrop"><form className="modal-card" onSubmit={async e=>{e.preventDefault();if(newName.trim()){try{const result=await api<any>('/customers',{method:'POST',body:JSON.stringify({fullName:newName,phone:newPhone,email:newEmail})});const c=result.customer;setRows([[c.fullName,c.phone||'',c.email||'','Active',new Date(c.createdAt).toLocaleDateString('en-IN')],...rows]);setNewName('');setNewPhone('');setNewEmail('');setShowAdd(false);setApiError('')}catch(err){setApiError(err instanceof Error?err.message:'Could not save customer.')}}}}><div className="modal-head"><div><h2>Add customer</h2><p>Create a new customer record.</p></div><button type="button" className="icon-button" onClick={()=>setShowAdd(false)}><X/></button></div><div className="modal-fields"><label>Customer name<input required value={newName} onChange={e=>setNewName(e.target.value)} placeholder="Full name"/></label><label>Phone number<input type="tel" value={newPhone} onChange={e=>setNewPhone(e.target.value)} placeholder="+91 98765 43210"/></label><label className="modal-field-wide">Email address<input type="email" value={newEmail} onChange={e=>setNewEmail(e.target.value)} placeholder="name@example.com"/></label><label>Status<select defaultValue="Active"><option>Active</option><option>Inactive</option></select></label></div><div className="modal-actions"><button type="button" className="btn btn-outline" onClick={()=>setShowAdd(false)}>Cancel</button><button className="btn btn-primary" type="submit">Save customer</button></div></form></div>}</>}
